import type { DescMessage } from "@bufbuild/protobuf";
import type { GeneratedFile } from "@bufbuild/protoplugin";
import { getProtoAnnotationEntries, type ProtoAnnotationEntry } from "./source-comments.js";

function printAnnotationMap(f: GeneratedFile, name: string, entries: readonly ProtoAnnotationEntry[]): void {
  if (entries.length === 0) {
    return;
  }
  f.print(`  ${name}: {`);
  for (const entry of entries) {
    f.print("    ", f.string(entry.key), ": ", f.string(entry.value), ",");
  }
  f.print("  },");
}

export function generateMessageAnnotations(f: GeneratedFile, message: DescMessage, runtimeImport: string): string {
  const registerProtoAnnotations = f.import("registerProtoAnnotations", runtimeImport);
  const messageSchema = f.importSchema(message);
  const annotationsName = `${message.name}FormAnnotations`;
  const annotations = getProtoAnnotationEntries(message);

  f.print(f.jsDoc(`Source documentation for ${message.typeName}.`));
  f.print(f.export("const", annotationsName), " = {");
  printAnnotationMap(f, "fields", annotations.fields);
  printAnnotationMap(f, "messages", annotations.messages);
  printAnnotationMap(f, "oneofs", annotations.oneofs);
  f.print("} as const;");
  f.print(registerProtoAnnotations, "(", messageSchema, ", ", annotationsName, ");");
  f.print();

  return annotationsName;
}

import type { DescMessage } from "@bufbuild/protobuf";
import { createEcmaScriptPlugin, type GeneratedFile, type Schema } from "@bufbuild/protoplugin";
import { generateMessageAnnotations } from "./generate-annotations.js";

const DEFAULT_RUNTIME_IMPORT = "@/lib/protobuf-provider";
export const pluginVersion = "1.0.0";

interface ProtoformPluginOptions {
  runtimeImport: string;
}

function parseOptions(rawOptions: { key: string; value: string }[]): ProtoformPluginOptions {
  const runtimeImports = rawOptions.filter((option) => option.key === "runtime_import");
  if (runtimeImports.length > 1) {
    throw new Error("runtime_import can only be specified once");
  }
  const unknown = rawOptions.find((option) => option.key !== "runtime_import");
  if (unknown) {
    throw new Error(`unknown option ${unknown.key}`);
  }
  return {
    runtimeImport: runtimeImports[0]?.value || DEFAULT_RUNTIME_IMPORT,
  };
}

function generateMessageBinding(f: GeneratedFile, message: DescMessage, runtimeImport: string): void {
  const createProtoFormSchema = f.import("createProtoFormSchema", runtimeImport);
  const parseProtoSchema = f.import("parseProtoSchema", runtimeImport);
  const protoToFormValues = f.import("protoToFormValues", runtimeImport);
  const messageSchema = f.importSchema(message);
  const annotationsName = generateMessageAnnotations(f, message, runtimeImport);

  f.print(f.jsDoc(`Form binding for message ${message.typeName}.`));
  f.print(f.export("const", `${message.name}FormBinding`), " = {");
  f.print("  annotations: ", annotationsName, ",");
  f.print(
    "  createFormSchema: (options?: Parameters<typeof ",
    createProtoFormSchema,
    ">[1]) => ",
    createProtoFormSchema,
    "(",
    messageSchema,
    ", options),"
  );
  f.print("  defaultValues: () => ", protoToFormValues, "(", messageSchema, "),");
  f.print("  descriptor: ", messageSchema, ",");
  f.print("  parseSchema: () => ", parseProtoSchema, "(", messageSchema, "),");
  f.print("} as const;");
}

function generateTs(schema: Schema<ProtoformPluginOptions>): void {
  for (const file of schema.files) {
    if (file.messages.length === 0) {
      continue;
    }
    const f = schema.generateFile(`${file.name}_form.ts`);
    f.preamble(file);
    for (const [index, message] of file.messages.entries()) {
      if (index > 0) {
        f.print();
      }
      generateMessageBinding(f, message, schema.options.runtimeImport);
    }
  }
}

export const protocGenProtoform = createEcmaScriptPlugin({
  generateTs,
  name: "protoc-gen-protoform",
  parseOptions,
  version: `v${pluginVersion}`,
});

// Executable entry point: reads a CodeGeneratorRequest from stdin and
// writes a CodeGeneratorResponse to stdout. Used by the bin wrapper and
// by repo-internal buf templates running the plugin from source via bun.
import { runNodeJs } from "@bufbuild/protoplugin";
import { protocGenProtoform } from "./plugin.js";

runNodeJs(protocGenProtoform);

import type { DescMessage } from "@bufbuild/protobuf";
import { getComments } from "@bufbuild/protoplugin";

export interface ProtoAnnotationEntry {
  key: string;
  value: string;
}

function sourceFileMessages(message: DescMessage): DescMessage[] {
  const messages: DescMessage[] = [];
  const visited = new Set<string>();

  function visit(current: DescMessage): void {
    if (current.file !== message.file || visited.has(current.typeName)) {
      return;
    }
    visited.add(current.typeName);
    messages.push(current);

    for (const nested of current.nestedMessages) {
      visit(nested);
    }
    for (const field of current.fields) {
      if (field.fieldKind === "message") {
        visit(field.message);
      } else if (field.fieldKind === "list" && field.listKind === "message") {
        visit(field.message);
      } else if (field.fieldKind === "map" && field.mapKind === "message") {
        visit(field.message);
      }
    }
  }

  visit(message);
  return messages;
}

function sourceComment(desc: Parameters<typeof getComments>[0]): string | undefined {
  const comment = getComments(desc).leading?.trim();
  return comment || undefined;
}

export function getProtoAnnotationEntries(message: DescMessage): {
  fields: ProtoAnnotationEntry[];
  messages: ProtoAnnotationEntry[];
  oneofs: ProtoAnnotationEntry[];
} {
  const messages = sourceFileMessages(message);
  return {
    fields: messages.flatMap((nested) =>
      nested.fields.flatMap((field) => {
        const comment = sourceComment(field);
        return comment
          ? [
              {
                key: `${field.parent.typeName}.${field.localName}`,
                value: comment,
              },
            ]
          : [];
      })
    ),
    messages: messages.flatMap((nested) => {
      const comment = sourceComment(nested);
      return comment ? [{ key: nested.typeName, value: comment }] : [];
    }),
    oneofs: messages.flatMap((nested) =>
      nested.oneofs.flatMap((oneof) => {
        const comment = sourceComment(oneof);
        return comment
          ? [
              {
                key: `${oneof.parent.typeName}.${oneof.localName}`,
                value: comment,
              },
            ]
          : [];
      })
    ),
  };
}
